with base as (select *, case when city = 'New York' then 1 else 0 end as is_new_york from stores where region <> 'East' and sqft between 4686 and 9532 and city not in ('Bangkok', 'Chiang Mai')), city_summary as (select city, region, sum(case when city = 'New York' then sqft else 0 end) as new_york_sqft, avg(sqft) as avg_sqft from base group by city, region) select city, region, new_york_sqft, avg_sqft from city_summary
